"""Manual cash flows; expected amounts are not generated by the implementation.

AI assistance: ChatGPT; matches the hand examples specified in issue #8.
"""

import json
from pathlib import Path

import pytest

from finmath.finance import Fill, HedgeAccount, Instrument, ShortCall, normalized_shortfall

CENT = Instrument(2, 1, 1_000_000)


@pytest.mark.parametrize(
    "close,expected_cash,expected_pnl",
    [(11_000, 8522, 1522), (10_000, 10522, 522), (9000, 10522, -2478)],
)
def test_partial_fill_funding_and_settlement_match_manual_example(
    close: int, expected_cash: int, expected_pnl: int
) -> None:
    opening = HedgeAccount(CENT, 20_000, net_lots=2)
    baseline = opening.equity(10_000)
    issued = opening.issue(ShortCall(2, 10_000, 250, 0, 2))
    # Target was +3 shares, but only one share actually filled.
    first = issued.advance_day(
        10_000,
        (Fill(1, 10_000),),
        commission=0.001,
        annual_funding_rate=0.252,
        days_per_year=252,
    )
    assert first.cash_units == 10511
    end = first.advance_day(close, annual_funding_rate=0.252)
    assert baseline == 40_000
    assert end.net_lots == 3
    assert end.cash_units == expected_cash
    assert end.pnl(baseline, close) == expected_pnl
    assert end.call is None
    assert issued.cash_units == 20_500  # The opening state is unchanged.


def test_roll_keeps_holdings_cash_and_settles_only_once() -> None:
    start = HedgeAccount(CENT, 100).issue(ShortCall(1, 100, 10, 0, 1))
    settled = start.advance_day(120)
    assert settled.cash_units == 90
    rolled = settled.issue(ShortCall(1, 120, 15, 1, 3))
    next_day = rolled.advance_day(120)
    assert next_day.cash_units == 105 and next_day.call == rolled.call
    assert rolled.net_lots == settled.net_lots
    with pytest.raises(ValueError):
        rolled.issue(ShortCall(1, 120, 1, 1, 2))


def test_burn_in_rebasing_and_live_call_marks() -> None:
    start = HedgeAccount(CENT, 10_000)
    issued = start.issue(ShortCall(1, 10_000, 100, 0, 2))
    cutoff = issued.advance_day(10_500)
    with pytest.raises(ValueError):
        cutoff.equity(10_500)
    cutoff_value = cutoff.equity(10_500, call_mark_per_share_units=150)
    end = cutoff.advance_day(11_000)
    assert end.pnl(cutoff_value, 11_000) == -850
    assert end.pnl(start.equity(10_000), 11_000) == -900
    with pytest.raises(ValueError):
        end.equity(11_000, call_mark_per_share_units=1)


def test_negative_cash_and_sell_fills_are_not_reset() -> None:
    start = HedgeAccount(CENT, 0)
    long = start.advance_day(10_000, (Fill(1, 10_000),), commission=0.001)
    assert long.cash_units == -10_010
    funded = long.advance_day(10_000, annual_funding_rate=0.252)
    assert funded.cash_units == -10_020
    flat = funded.advance_day(11_000, (Fill(-1, 11_000),), commission=0.001)
    assert flat.net_lots == 0 and flat.cash_units == 969


def test_fee_precision_changes_without_changing_stock_price_or_quantity() -> None:
    cents = Instrument(2, 1, 10_000)
    precise = Instrument(8, 1_000_000, 10_000)
    assert cents.fee(cents.stock_value(10_000, 2), 0.001) == 0
    assert precise.fee(precise.stock_value(10_000, 2), 0.001) == 200_000
    assert cents.stock_value(10_000, 2) / 100 == precise.stock_value(10_000, 2) / 100_000_000
    assert cents.fee(50, 0.01) == 1  # Half a cash unit rounds away from zero.
    assert cents.funding(-50, 0.01, 1) == -1
    assert cents.price_units(1.005) == 101
    assert precise.price_units(0.002) == 200_000


@pytest.mark.parametrize(
    "commission,expected_fee",
    [(0, 0), (0.0005, 100_000), (0.001, 200_000), (0.002, 400_000), (0.004, 800_000)],
)
def test_small_fills_keep_all_five_research_commission_levels(
    commission: float, expected_fee: int
) -> None:
    precise = Instrument(8, 1_000_000, 10_000)
    # 0.02 shares * $100 = $2 notional, with cash units of 1e-8 USD.
    assert precise.fee(precise.stock_value(10_000, 2), commission) == expected_fee


def test_invalid_events_leave_original_account_available() -> None:
    start = HedgeAccount(CENT, 100)
    with pytest.raises(ValueError):
        start.advance_day(100, (Fill(1, 100),), commission=-1)
    assert start.cash_units == 100 and start.net_lots == 0 and start.step == 0
    with pytest.raises(ValueError):
        start.advance_day(100, days_per_year=0)
    with pytest.raises(ValueError):
        Instrument(2, 1.5, 1000)
    with pytest.raises(ValueError):
        Fill(0, 100)
    with pytest.raises(ValueError):
        ShortCall(1, 100, 1, 0, 0)


def test_shared_financial_fixtures_match_the_reference() -> None:
    fixture = Path(__file__).parent.parent / "fixtures/finance-reference.json"
    data = json.loads(fixture.read_text())
    for case in data["accounting_cases"]:
        start = HedgeAccount(CENT, case["opening_cash_units"], case["opening_lots"])
        base = start.equity(case["opening_price_ticks"])
        account = start.issue(ShortCall(**case["call"]))
        first = account.advance_day(
            case["first_close_ticks"],
            tuple(Fill(**fill) for fill in case["fills"]),
            commission=case["commission"],
            annual_funding_rate=case["annual_funding_rate"],
        )
        end = first.advance_day(
            case["close_ticks"], annual_funding_rate=case["annual_funding_rate"]
        )
        assert end.cash_units == case["expected_cash_units"]
        assert end.pnl(base, case["close_ticks"]) == case["expected_pnl_units"]


def test_normalized_shortfall_sign_and_units() -> None:
    assert normalized_shortfall(-2489, 10_000, 2) == pytest.approx(0.12445)
    assert normalized_shortfall(1511, 10_000, 2) == pytest.approx(-0.07555)
    with pytest.raises(ValueError):
        normalized_shortfall(100, 0, 1)


def test_binary_float_rate_boundaries_match_the_shared_rust_fixture() -> None:
    path = Path(__file__).parent.parent / "fixtures/finance-reference.json"
    for case in json.loads(path.read_text())["rate_cases"]:
        amount, rate, expected = case["notional_units"], case["rate"], case["expected_units"]
        assert CENT.funding(amount, rate, 1) == expected
        if rate >= 0:
            assert CENT.fee(amount, rate) == expected
